window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e10a64049c3c2700"]={"versions": [{"id": "FIG-e10a64049c3c2700", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit den Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien auf Metamodellebene ermöglicht. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-bb4b45bf406170b2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit den Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien auf Metamodellebene ermöglicht. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-e05b67e9c03e2be6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit den Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien auf Metamodellebene ermöglicht. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-1082be782ff98286", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>Komposition <code>+fileInfoComment 0..1</code> zu FileInfoComment mit Stereotyp <code>«atpStructuredComment»</code>.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>FileInfoComment: Metaklasse für strukturierte Dateikommentare, annotiert mit der Notiz „These elements have no semantics in the model and may be ignored on model level.“.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien ermöglicht. Die Assoziation <code>fileInfoComment</code> erlaubt das Führen von Datei-Header-Kommentaren ohne semantischen Einfluss auf Modellebene. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-0c015dabb191bd80", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>Komposition <code>+fileInfoComment 0..1</code> zu FileInfoComment mit Stereotyp <code>«atpStructuredComment»</code>.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>FileInfoComment: Metaklasse für strukturierte Dateikommentare, annotiert mit der Notiz „These elements have no semantics in the model and may be ignored on model level.“.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien ermöglicht. Die Assoziation <code>fileInfoComment</code> erlaubt das Führen von Datei-Header-Kommentaren ohne semantischen Einfluss auf Modellebene. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-f852172bf7cddddc", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>Komposition <code>+fileInfoComment 0..1</code> zu FileInfoComment mit Stereotyp <code>«atpStructuredComment»</code>.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>FileInfoComment: Metaklasse für strukturierte Dateikommentare, annotiert mit der Notiz „These elements have no semantics in the model and may be ignored on model level.“.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien ermöglicht. Die Assoziation <code>fileInfoComment</code> erlaubt das Führen von Datei-Header-Kommentaren ohne semantischen Einfluss auf Modellebene. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}, {"id": "FIG-b51d20779d475386", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung der obersten Struktur (Top-Level-Struktur) der AUTOSAR-Vorlagen (Generic Structure Template). Es modelliert die globale Wurzelklasse, Paketierungsmechanismen, Metadatenzuordnungen sowie das Vererbungsfundament der AUTOSAR-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>AUTOSAR: Globale Wurzel-Metaklasse aller AUTOSAR-Templates.</li>\n<li>Komposition <code>+arPackage 0..*</code> zu ARPackage mit Stereotypen <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+introduction 0..1</code> zu DocumentationBlock.</li>\n<li>Komposition <code>+adminData 0..1</code> zu AdminData.</li>\n<li>Komposition <code>+fileInfoComment 0..1</code> zu FileInfoComment mit Stereotyp <code>«atpStructuredComment»</code>.</li>\n<li>ARPackage: Paketierungsknoten mit Spezialisierungen/Interfaces AtpBlueprint, AtpBlueprintable, CollectableElement, Identifiable.</li>\n<li>Rekursive Komposition <code>+arPackage 0..*</code> auf sich selbst mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>Komposition <code>+element 0..*</code> zu PackageableElement mit <code>«atpSplitable,atpVariation»</code>.</li>\n<li>PackageableElement: Abstrakte Elementbasis in Paketen (CollectableElement, Identifiable).</li>\n<li>ARElement: Spezialisierung von PackageableElement, Basis für spezifische AUTOSAR-Artefakte.</li>\n<li>Spezialisierungen unter anderem: AutosarDataType (mit AtpType) sowie Unit (<code>+ factorSiToUnit: Float [0..1]</code>, <code>+ offsetSiToUnit: Float [0..1]</code>).</li>\n<li>AdminData: Administrationsdatenblock mit Attribut <code>+ language: LEnum [0..1]</code>.</li>\n<li>DocumentationBlock: Strukturierter Dokumentationstext mit Stereotyp <code>«atpMixed»</code>.</li>\n<li>FileInfoComment: Metaklasse für strukturierte Dateikommentare, annotiert mit der Notiz „These elements have no semantics in the model and may be ignored on model level.“.</li>\n<li>ARObject: Stereotyp <code>«atpObject»</code>, implizite Basisklasse aller Klassen im Modell (per Notiz annotiert), Attribute <code>+ checksum: String [0..1]</code>, <code>+ timestamp: DateTime [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablauf- oder Sequenzlogik. Die strukturellen Assoziationen definieren die hierarchische Schachtelung von Paketen und die Einbettung von Modellelementen, Administrationsdaten und Dokumentationsblöcken in AUTOSAR-XML-Beschreibungsdateien.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Wurzelklasse AUTOSAR bildet den Einstiegspunkt für AUTOSAR-Modellinstanzen. Durch die Stereotype <code>«atpSplitable»</code> und <code>«atpVariation»</code> an den Kompositionen <code>arPackage</code> und <code>element</code> wird die physische Aufteilung über mehrere Dateigrenzen hinweg sowie die Bindung an Variantenkriterien ermöglicht. Die Assoziation <code>fileInfoComment</code> erlaubt das Führen von Datei-Header-Kommentaren ohne semantischen Einfluss auf Modellebene. ARObject stattet alle Modellelemente implizit mit Integritäts- und Versionierungsattributen (Prüfsumme, Zeitstempel) aus.</p>"}], "trans": [{"from": "FIG-e10a64049c3c2700", "to": "FIG-bb4b45bf406170b2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bb4b45bf406170b2", "to": "FIG-e05b67e9c03e2be6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e05b67e9c03e2be6", "to": "FIG-1082be782ff98286", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>AUTOSAR: Ergänzung der Kompositionsbeziehung <code>+fileInfoComment 0..1</code> zur Klasse <code>FileInfoComment</code> mit Stereotyp <code>«atpStructuredComment»</code>.</li>\n<li>FileInfoComment: Neue Metaklasse mit zugeordneter Notiz „These elements have no semantics in the model and may be ignored on model level.“.</li>\n</ul>"}, {"from": "FIG-1082be782ff98286", "to": "FIG-0c015dabb191bd80", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0c015dabb191bd80", "to": "FIG-f852172bf7cddddc", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f852172bf7cddddc", "to": "FIG-b51d20779d475386", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
